$ok = @([regex]::Matches($out, '"(build:[^"]+)":\s*"') | % { $_.Groups[1].Value })
"  " + $ok.Count + " of " + $keys.Count + " read back"
$keys | ? { $ok -notcontains $_ } | % { "  STILL MISSING: " + $_ }
